@font-face { font-family: 'Lilita One'; src: url('assets/fonts/LilitaOne-Regular.woff2') format('woff2'); font-weight: 400; }
    .inner.hook { font-family: 'Lilita One', sans-serif; font-weight: 400; font-size: 98px; line-height: 1.12; letter-spacing: .01em; top: -560px; }
    .inner.hook .bar { background: #ff3d7f !important; padding: .02em .3em .08em; border-radius: .5em; }
    .inner.hook .w { color: #fff; }
    .inner .bar .w { margin: 0 .07em; }
    .inner .bar { border-radius: .55em; padding: .04em .36em .1em; }
    .inner .w { white-space: nowrap; }
    .inner.hook .w { display: inline-block; transform-origin: 50% 70%; }
    .inner.hook .bar { background: none !important; box-shadow: none !important; padding: 0; }
    .inner.hook .w { background: #ff3d7f; border-radius: .3em; padding: .02em .16em .1em; margin: .07em .03em; box-shadow: 0 0 0 0px #2a1b12, 0 8px 0 rgba(0,0,0,.28); position: relative; transform-origin: 50% 55%; }
    .inner.hook .w.k-y { position: relative; z-index: 2; }
    #cgi1.inner.hook, #cgi2.inner.hook { top: 0; }
    .inner.hook { left: 40px; right: 40px; }
    #cgi1 .w, #cgi2 .w { margin: .1em .12em; }
    .grp { top: 1430px !important; }
    .inner { font-size: 70px !important; }
